# ================= ГЕНЕРАЦИЯ MARKDOWN =================
def gen_md():
    out = []
    out.append("# Дизайн мода «СССР: 1980–2080» · v2")
    out.append("")
    out.append("## Структура решений (3 уровня)")
    out.append("")
    out.append("Каждое решение игрока разворачивается в **дугу последствий** — не «один флаг», а три последовательных события:")
    out.append("")
    out.append("```")
    out.append("РОМБ  событие (год)")
    out.append(" ├─ ПРЯМОУГОЛЬНИК  решение №1  ──►  дуга:  НАЧАЛО → КУЛЬМИНАЦИЯ → ФИНАЛ")
    out.append(" │                                     │          │              │")
    out.append(" │                                   (по 3      (по 3          (по 3")
    out.append(" │                                    решения)   решения)       решения)")
    out.append(" └─ …ещё 2 решения, у каждого своя дуга")
    out.append("```")
    out.append("")
    out.append("**Правила:**")
    out.append("1. **Начало → Кульминация → Финал** идут строго по порядку (последовательно, не одновременно).")
    out.append("2. У каждого из трёх событий дуги — **свои 3 решения**.")
    out.append("3. Решения внутри дуги — **терминальные**: они дают эффекты/штрафы/флаги, но **не порождают новых событий**.")
    out.append("4. Долгие эффекты (радиация, штрафы) «тают» со временем — это **механика** движка (модификаторы с убыванием), а не сценарий. В сценарии фиксируется только сам факт штрафа.")
    out.append("")
    out.append("**Цвета:** 🔴 консерватор/жёсткий · 🟡 центрист/компромисс · 🟢 реформатор/либеральный.")
    out.append("")
    out.append("---")
    out.append("")
    out.append("# ЭПОХА 1 · 1980–1991")
    out.append("")
    n = 1
    for e in EVENTS:
        trig = f" *(условие: {e['trigger']})*" if e['trigger'] else ""
        out.append(f"## {n}. {e['year']} · {e['title']}{trig}")
        out.append("")
        for (c, label, arc) in e['decisions']:
            out.append(f"- {EMOJI[c]} **{label}**")
            for (stage, sub, choices) in arc:
                clist = " / ".join(f"`{t}`" for (_c, t) in choices)
                out.append(f"  - **{stage}** — «{sub}» → {clist}")
        out.append("")
        n += 1
    out.append("---")
    out.append("")
    out.append("# После путча — три магистральные ветки (Эпоха 2+)")
    out.append("")
    out.append("- **Ветка А · «ГКЧП»** — СССР сохранён, жёсткий/мягкий курс.")
    out.append("- **Ветка Б · «Распад»** — 15 республик, у каждой свой сценарный путь.")
    out.append("- **Ветка В · «Конфедерация (ССГ)»** — обновлённый Союз.")
    out.append("")
    out.append("> Детализацию веток распишем по той же трёхуровневой модели.")
    out.append("")
    return "\n".join(out)

# ================= ГЕНЕРАЦИЯ MERMAID =================
def gen_mmd(e, idx):
    L = []
    slug = f"ev{idx}"
    L.append("flowchart TD")
    trig = f"<br/><i>{e['trigger']}</i>" if e['trigger'] else ""
    title = f"{e['year']} · {e['title']}"
    L.append(f'    X{{"{title}{trig}"}}:::event')
    for i,(c,label,arc) in enumerate(e['decisions']):
        di = f"{slug}d{i}"
        L.append(f'    {di}["{label}"]:::{MCOL[c]}')
        L.append(f"    X --> {di}")
        stages = []
        for j,(stage,sub,choices) in enumerate(arc):
            si = f"{slug}d{i}s{j}"
            L.append(f'    {si}{{"{stage}<br/>{sub}"}}:::sub')
            stages.append(si)
        L.append(f"    {stages[0]} --> {stages[1]} --> {stages[2]}")
        L.append(f"    {di} --> {stages[0]}")
        for j,(stage,sub,choices) in enumerate(arc):
            si = f"{slug}d{i}s{j}"
            for k,(cc,t) in enumerate(choices):
                ti = f"{si}t{k}"
                L.append(f'    {ti}["{t}"]:::{MCOL[cc]}')
                L.append(f"    {si} --> {ti}")
    L.append("")
    L.append("    classDef event fill:#eef1f5,stroke:#33507a,stroke-width:2.5px,color:#20304a,font-weight:bold")
    L.append("    classDef sub fill:#f4f6fa,stroke:#7a8ca8,stroke-width:1.5px,color:#33445c")
    L.append("    classDef red fill:#fce8e6,stroke:#d9534f,stroke-width:1.5px,color:#7a1f1f")
    L.append("    classDef yellow fill:#fdf3d0,stroke:#d9a514,stroke-width:1.5px,color:#6d5400")
    L.append("    classDef green fill:#e3f4e6,stroke:#5cb85c,stroke-width:1.5px,color:#1e5c28")
    return "\n".join(L)

def slugify(e, idx):
    t = e['title'].split(':')[0].split('(')[0].strip()
    t = t.replace('★','').replace(' ','_').replace('«','').replace('»','')
    return f"{idx:02d}_{e['year']}_{t}"

def main():
    os.makedirs("/home/user/diagrams", exist_ok=True)
    # markdown
    md = gen_md()
    with open("/home/user/дизайн_мода_СССР_1980_2080.md","w",encoding="utf-8") as f:
        f.write(md)
    # mermaid
    for idx, e in enumerate(EVENTS, 1):
        mmd = gen_mmd(e, idx)
        fn = f"/home/user/diagrams/{slugify(e,idx)}.mmd"
        with open(fn,"w",encoding="utf-8") as f:
            f.write(mmd)
    print("Сгенерировано:", len(EVENTS), "схем + документ")

if __name__ == "__main__":
    main()


